{"j_sock_and_buskin","retrigger","Retriggers all played face cards.","Core of face card builds. Pair with Pareidolia.",c="j_pareidolia,j_photograph,j_smiley,j_scary_face,j_triboulet,j_midas_mask",a="face_cards,retrigger"},
{"j_swashbuckler","mult","Adds the sell value of all other owned jokers to Mult.","Good with Egg, Gift Card and valuable jokers; mid power. Selling other jokers lowers it.",c="j_egg,j_gift",a="mult_stack,economy"},
{"j_troubadour","hand_size","+2 hand size, -1 hand each round.","Good for flush and straight plans with enough extra hands; risky otherwise.",c="j_juggler",a="flush,straight"},
{"j_certificate","util","Adds a random card with a random seal to your hand each round.","Good for deck fattening; stronger with Hologram and Glass or Steel plans. Free seals are strong.",c="j_hologram,j_dna",a="deck_fattening"},
{"j_smeared","util","Hearts and Diamonds count as the same suit; Spades and Clubs count as the same.","Huge for flush: you only need two suits worth of cards. Take for flush plans mid run.",c="j_four_fingers,j_ancient,j_greedy_joker,j_lusty_joker,j_wrathful_joker,j_gluttenous_joker,j_flower_pot,j_seeing_double",a="flush"},
{"j_throwback","xmult","Gains X0.25 Mult for each blind skipped this run.","Good if you skip blinds for tags; skip tags like Investment or Voucher. Strong in a skip heavy plan.",c="j_red_card,tag_investment",a="scaling_jokers,xmult_stack",scale=1.1},
{"j_hanging_chad","retrigger","Retriggers the first scored card two additional times.","Strong with Hiker, Lucky and glass first-card plans; and for steel scoring cards. Great mid run.",c="j_hiker,j_photograph,j_lucky_cat,j_dusk",a="retrigger"},
{"j_rough_gem","econ","Scored Diamonds earn $1.","Good in a Diamond flush plan economy.",c="j_smeared,j_greedy_joker",suit="Diamonds",a="flush,economy"},
{"j_bloodstone","xmult","Scored Hearts have a 1 in 2 chance to give X1.5 Mult.","Strong in Heart flush plans; Oops all 6s makes it always. Retriggers also help.",c="j_oops,j_smeared,j_lusty_joker,j_hanging_chad",suit="Hearts",a="flush,xmult_stack"},
{"j_arrowhead","chips","Scored Spades give +50 Chips.","Strong chips in Spade flush plans.",c="j_wrathful_joker,j_smeared,j_blackboard",suit="Spades",a="flush"},
{"j_onyx_agate","mult","Scored Clubs give +7 Mult.","Strong in Club flush plans.",c="j_gluttenous_joker,j_smeared",suit="Clubs",a="flush"},
{"j_glass","scaling","Gains X0.75 Mult for each Glass card destroyed.","Good in glass card builds; each shatter grows it. Stronger with Justice and Vampire-free decks.",c="m_glass,c_justice,j_oops",a="glass_cannon,scaling_jokers",scale=1.2},
{"j_ring_master","util","Joker, Tarot, Planet and Spectral cards may appear multiple times.","Niche; lets you stack duplicates like multiple Blueprints. Rarely worth a slot.",a="copy_chain"},
{"j_flower_pot","xmult","X3 Mult if the played hand contains a Diamond, Club, Heart and Spade card.","Strong with Wild cards and in four suit full hands; Smeared hurts it. Needs scoring cards of every suit; Wild and Splash help.",c="m_wild,j_splash,c_lovers,j_ancient",a="xmult_stack"},
{"j_merry_andy","util","+3 discards each round, -1 hand size.","Great for digging in flush and straight plans; the hand size cost is real. Combine with Juggler.",c="j_juggler,v_paint_brush",a="discard_engine,flush"},
{"j_oops","util","Doubles all listed probabilities.","Core of lucky card, Bloodstone, 8 Ball, Glass and Wheel of Fortune builds.",c="j_bloodstone,j_lucky_cat,m_lucky,m_glass,j_8_ball,c_wheel_of_fortune,j_business",a="lucky_cards,glass_cannon"},
{"j_idol","xmult","Each played card of a random rank and suit (changes each round) gives X2 Mult when scored.","Strong with the right card; you can build it with Cryptid or pairs of that card. Needs deck knowledge.",c="c_cryptid,j_dna",a="deck_fattening,xmult_stack"},
{"j_seeing_double","xmult","X2 Mult if the played hand has a scoring Club and a scoring card of another suit.","Good in Club heavy mixed suit builds; Wild cards help.",c="m_wild,j_smeared,j_flower_pot",suit="Clubs",a="xmult_stack"},
{"j_matador","econ","Earn $8 if a played hand triggers the Boss Blind ability.","Niche; good against bosses that trigger on play such as The Tooth. Do not buy as a general economy joker.",a="economy"},
{"j_hit_the_road","scaling","Gains X0.5 Mult for each Jack discarded this round; resets each round.","Strong in Jack heavy decks and discard plans. Needs Jacks in the deck.",c="j_castle,j_mail",rank="J",a="discard_engine,scaling_jokers",scale=1.1},
{"j_duo","xmult","X2 Mult if the played hand contains a Pair.","Strong in pair builds; stacks with the other family jokers by hand type.",c="j_trio,j_family,j_jolly,j_sly",h="P,TP,3K,FH,4K",a="pair"},
{"j_trio","xmult","X3 Mult if the played hand contains Three of a Kind.","Strong in trips and full house builds.",c="j_duo,j_zany,j_family",h="3K,FH,4K",a="three_kind,full_house"},
{"j_family","xmult","X4 Mult if the played hand contains Four of a Kind.","Strong for a four of a kind plan, with Cryptid and DNA deck stacking.",c="j_duo,j_trio,c_cryptid,j_dna",h="4K",a="four_kind"},
{"j_order","xmult","X3 Mult if the played hand contains a Straight.","Strong in straight builds with Shortcut.",c="j_shortcut,j_four_fingers,j_runner",h="ST,SF",a="straight"},
{"j_tribe","xmult","X2 Mult if the played hand contains a Flush.","Strong in flush builds.",c="j_four_fingers,j_smeared,j_droll,j_crafty",h="FL,SF,FHF,FF",a="flush"},
{"j_stuntman","chips","+250 Chips, -2 hand size.","Strong for chip heavy builds; the hand size loss hurts flush and straight plans. Pair with Juggler and Troubadour; best with high card.",c="j_juggler",a="high_card"},
{"j_invisible","copy","After 2 rounds, selling it duplicates a random joker.","Keep for 2 rounds, then sell with a good joker on board; the copy can be your best xMult. Randomly selected, keep only good jokers.",c="j_blueprint",a="copy_chain"},
{"j_brainstorm","copy","Copies the ability of the leftmost joker.","Put it as the second joker with your best xMult first. Strong with Baron and Mime plans and Photograph.",c="j_blueprint,j_baron,j_cavendish",a="copy_chain"},
{"j_satellite","econ","Earn $1 at end of round for each unique Planet card used this run.","Good in planet builds early; scales with Celestial packs.",c="j_constellation,v_telescope,v_planet_merchant",a="planet_scaling,economy"},
{"j_shoot_the_moon","mult","Each Queen held in hand gives +13 Mult.","Good with Mime, and Queen holding builds; Pareidolia irrelevant.",c="j_mime,j_baron,j_raised_fist",rank="Q",a="steel_kings"},
{"j_drivers_license","xmult","X3 Mult if you have at least 16 Enhanced cards in your full deck.","Strong in enhancement-heavy decks with Tarot and Spectrals; needs 16 enhanced cards. Hard before ante 4.",c="c_empress,c_heirophant,c_magician,c_justice,c_chariot,j_midas_mask",a="tarot_scaling,xmult_stack"},
{"j_cartomancer","util","Creates a Tarot card when the blind is selected.","Good for tarot supply, but needs consumable slot.",c="j_fortune_teller,j_hallucination",a="tarot_scaling"},
{"j_astronomer","util","All Planet cards and Celestial Packs in the shop are free.","Strong in planet scaling and Constellation builds. Skip otherwise.",c="j_constellation,j_satellite,v_telescope",a="planet_scaling"},
{"j_burnt","util","Upgrades the level of the first discarded poker hand each round.","Good with a single hand type you discard and play; compounds with levels.",c="j_space,j_supernova",a="planet_scaling,discard_engine",scale=1.1},
{"j_bootstraps","mult","+2 Mult for every $5 you have.","Strong with an economy engine; Seed Money, Money Tree, To the Moon.",c="j_to_the_moon,j_bull,v_seed_money",a="economy,mult_stack"},
{"j_caino","scaling","Gains X1 Mult when a face card is destroyed.","Legendary; strong with Glass face cards and Hanged Man on faces.",c="m_glass,c_hanged_man,c_death,j_glass",a="glass_cannon,scaling_jokers,face_cards",scale=1.35},
{"j_triboulet","xmult","Played Kings and Queens each give X2 Mult when scored.","Legendary; wins face card builds, Pareidolia makes it work on every card. Retriggers double it.",c="j_sock_and_buskin,j_pareidolia,j_hanging_chad,j_dusk",rank="K,Q",a="face_cards,xmult_stack"},
{"j_yorick","scaling","Gains X1 Mult every 23 cards discarded.","Legendary; strong in discard heavy builds.",c="j_merry_andy,j_drunkard,v_wasteful",a="scaling_jokers,discard_engine",scale=1.25},
{"j_chicot","util","Disables the effect of every Boss Blind.","Legendary; removes boss risk, good for any build.",a="survival"},
{"j_perkeo","util","Creates a Negative copy of 1 random consumable at end of the shop.","Legendary; great with planets and tarots like The Fool and Strength setups. Doubles consumables each shop; strong in planet scaling.",c="c_black_hole,c_fool,c_wheel_of_fortune,c_cryptid",a="planet_scaling,tarot_scaling"},
{"j_blueprint","copy","Copies the ability of the joker to its right.","Put it directly left of your best xMult or retrigger joker. Take almost always; the best copy piece. Keep jokers to its right stable and not Eternal-less sold.",c="j_brainstorm,j_baron,j_cavendish,j_photograph,j_triboulet,j_duo,j_mime",a="copy_chain,xmult_stack"},
{"j_wee","scaling","Gains +8 Chips each time a 2 is scored.","Good with 2 heavy decks and retriggers like Hack, Hanging Chad; fast chip scaling in a deck thinned to low cards.",c="j_hack,j_hanging_chad,j_dusk,j_selzer,j_fibonacci",rank="2",a="scaling_jokers,retrigger",scale=1.15},
}

